const crypto = require('crypto');

// Generiert 12 sichere Zufallsbytes und wandelt sie direkt in Base64 um
const clientNonce = crypto.randomBytes(12).toString('base64');

// Übergibt den client_nonce an das nächste n8n-Element
return [{
  json: {
    ...$input.first().json,
    client_nonce: clientNonce
  }
}];

const crypto = require('crypto');

const username = "user";          // Wieder zurück auf "user" gestellt
const password = "<DEIN_INVERTER_PASSWORT>";       // Dein echtes Inverter-Passwort

// Eingabedaten aus den vorherigen Knoten abgreifen
const inverterData = $input.first().json;
const serverNonce = inverterData.nonce;
const saltBase64 = inverterData.salt;
const rounds = parseInt(inverterData.rounds, 10);
const transactionId = inverterData.transactionId;
const clientNonce = $('CreateNonce').first().json.client_nonce;

// 1. SaltedPassword per PBKDF2 (SHA-256) ableiten
const salt = Buffer.from(saltBase64, 'base64');
const saltedPassword = crypto.pbkdf2Sync(password, salt, rounds, 32, 'sha256');

// 2. ClientKey & StoredKey ableiten
const clientKey = crypto.createHmac('sha256', saltedPassword).update('Client Key').digest();
const storedKey = crypto.createHash('sha256').update(clientKey).digest();

// 3. AuthMessage nach RFC-5802 zusammensetzen
const authMessage = `n=${username},r=${clientNonce},r=${serverNonce},s=${saltBase64},i=${rounds},c=biws,r=${serverNonce}`;

// 4. ClientSignature & ClientProof berechnen
const clientSignature = crypto.createHmac('sha256', storedKey).update(authMessage).digest();

const clientProofBuf = Buffer.alloc(32);
for (let i = 0; i < 32; i++) {
  clientProofBuf[i] = clientKey[i] ^ clientSignature[i];
}
const clientProof = clientProofBuf.toString('base64');

// 5. Übergabe an den nächsten HTTP-Request-Knoten (/auth/finish)
return [{
  json: {
    transactionId: transactionId,
    proof: clientProof
  }
}];

const crypto = require('crypto');

// 1. Antwort von /auth/finish abgreifen (enthält token & signature)
const res = $input.first().json;
if (!res.token) {
  throw new Error("Kein Token in der /auth/finish Antwort gefunden!");
}

// 2. Daten aus vorherigen Knoten abrufen
const authStart = $('AuthStart').first().json;
const transactionId = authStart.transactionId;
const serverNonce = authStart.nonce;
const saltBase64 = authStart.salt;
const rounds = parseInt(authStart.rounds, 10);
const clientNonce = $('CreateNonce').first().json.client_nonce;

const username = "user";
const password = "<DEIN_INVERTER_PASSWORT>";

// 3. PBKDF2 & Keys ableiten (exakt wie in Postman)
const salt = Buffer.from(saltBase64, 'base64');
const saltedPassword = crypto.pbkdf2Sync(password, salt, rounds, 32, 'sha256');

const clientKey = crypto.createHmac('sha256', saltedPassword).update('Client Key').digest();
const storedKey = crypto.createHash('sha256').update(clientKey).digest();

// 4. AuthMessage zusammensetzen
const authMessage = `n=${username},r=${clientNonce},r=${serverNonce},s=${saltBase64},i=${rounds},c=biws,r=${serverNonce}`;

// 5. Exakter KOSTAL Protocol Session Key:
// HMAC-SHA256(key = storedKey, msg = "Session Key" + authMessage + clientKey)
const prefix = Buffer.from("Session Key" + authMessage, 'utf8');
const sessionKeyMsg = Buffer.concat([prefix, clientKey]);
const rawKey = crypto.createHmac('sha256', storedKey).update(sessionKeyMsg).digest();

// 6. 16-Byte IV generieren & Token per AES-256-GCM verschlüsseln
const iv = crypto.randomBytes(16);
const tokenBytes = Buffer.from(res.token, 'utf8');

const cipher = crypto.createCipheriv('aes-256-gcm', rawKey, iv);
let encrypted = cipher.update(tokenBytes);
encrypted = Buffer.concat([encrypted, cipher.final()]);
const tag = cipher.getAuthTag();

// 7. Übergabe an den /auth/create_session HTTP-Request
return [{
  json: {
    token: res.token,
    signature: res.signature,
    iv: iv.toString('base64'),
    payload: encrypted.toString('base64'),
    transactionId: transactionId,
    tag: tag.toString('base64')
  }
}];
